#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long MOD = 1000000007LL;
    int n;
    cin >> n;
    vector<vector<long long>> d(2 * n + 1, vector<long long>(n + 2, 0));
    d[0][0] = 1;
    for (int i = 1; i < 2 * n + 1; i++) {
        d[i][0] = d[i - 1][1] % MOD;
        for (int j = 1; j < n + 1 && j + i <= 2 * n; j++) {
            d[i][j] = (d[i - 1][j + 1] + d[i - 1][j - 1]) % MOD;
        }
    }
    long long totalSum = 0;
    for (int i = 2 * n - 1; i >= 0; i -= 2) {
        for (int j = 0; j <= n; j++) {
            totalSum += d[i][j];
            totalSum %= MOD;
        }
    }
    cout << totalSum << "\n";
    return 0;
}
